from contextlib import contextmanager

log = []

@contextmanager
def lock():
    log.append("lock")
    try:
        yield
    except ValueError:
        log.append("unlock")

with lock():
    log.append("работа")
print(log)

from contextlib import ExitStack

class Step:
    def __init__(self, n):
        self.n = n
    def __enter__(self):
        print("вход", self.n)
        return self.n
    def __exit__(self, *exc):
        print("выход", self.n)

with ExitStack() as stack:
    nums = [stack.enter_context(Step(i)) for i in range(1, 3)]
    print("внутри", nums)

